#include <bit>
#include <cstdint>
#include <optional>
#include <vector>

using Bytes = std::vector<std::uint8_t>;

static bool fits(const Bytes& bytes, std::size_t offset, std::size_t count)
{
    return offset <= bytes.size() && count <= bytes.size() - offset;
}

std::optional<std::uint32_t> readU32(const Bytes& bytes, std::size_t offset)
{
    if (!fits(bytes, offset, 4)) return std::nullopt;
    std::uint32_t value{ 0 };
    for (std::size_t i{ 0 }; i < 4; ++i)
        value |= static_cast<std::uint32_t>(bytes[offset + i]) << (8 * i);
    return value;
}

std::optional<std::int16_t> readI16(const Bytes& bytes, std::size_t offset)
{
    if (!fits(bytes, offset, 2)) return std::nullopt;
    const auto bits{ static_cast<std::uint16_t>(bytes[offset] | (bytes[offset + 1] << 8)) };
    return static_cast<std::int16_t>(bits);
}

std::optional<float> readF32(const Bytes& bytes, std::size_t offset)
{
    const auto bits{ readU32(bytes, offset) };
    if (!bits) return std::nullopt;
    return std::bit_cast<float>(*bits);
}

hints:
`std::optional<T>` (from `<optional>`) holds either a `T` or nothing. `return value;` gives back a filled one and `return std::nullopt;` an empty one. When you receive one, `if (!bits)` tests whether it is empty and `*bits` is the value inside.

```cpp
std::optional<int> half(int n) { if (n % 2 != 0) return std::nullopt; return n / 2; }
const auto h{ half(10) };
if (h) std::cout << *h;   // prints 5
```

unitTests:
const Bytes sample{ 0x0c, 0x00, 0x00, 0x00, 0x00, 0x00, 0x80, 0x3f, 0x9c, 0xff };
TEST("an unsigned int") { CHECK_EQ(*readU32(sample, 0), 12u); }
TEST("a float") { CHECK_NEAR(*readF32(sample, 4), 1.0, 1e-9); }
TEST("a negative short") { CHECK_EQ(*readI16(sample, 8), std::int16_t{ -100 }); }
TEST("past the end gives nothing") { CHECK(!readU32(sample, 8)); CHECK(!readI16(sample, 9)); CHECK(!readF32(sample, 7)); CHECK(!readU32(sample, 100)); }
TEST("exactly at the end is fine") { CHECK(readI16(sample, 8).has_value()); CHECK(readU32(sample, 6).has_value()); }
TEST("big values use all four bytes") { CHECK_EQ(*readU32(Bytes{ 0x78, 0x56, 0x34, 0x12 }, 0), 0x12345678u); CHECK_EQ(*readU32(Bytes{ 0xff, 0xff, 0xff, 0xff }, 0), 0xFFFFFFFFu); }
TEST("more floats") { CHECK_NEAR(*readF32(Bytes{ 0x00, 0x00, 0xc8, 0x42 }, 0), 100.0, 1e-9); CHECK_NEAR(*readF32(Bytes{ 0x00, 0x00, 0x80, 0xbf }, 0), -1.0, 1e-9); }
TEST("an empty block") { CHECK(!readU32(Bytes{}, 0)); }

